(x, y, t) => {
  const cx = 240, cy = 120;
  const warp1x = Math.sin(x*0.015+t*0.3)*20 + Math.cos(y*0.012-t*0.2)*15;
  const warp1y = Math.cos(y*0.015-t*0.25)*20 + Math.sin(x*0.013+t*0.35)*15;
  const warp2x = Math.sin((x+warp1x)*0.008+t*0.15)*30 + Math.cos((y+warp1y)*0.01-t*0.1)*20;
  const warp2y = Math.cos((y+warp1y)*0.008-t*0.12)*30 + Math.sin((x+warp1x)*0.009+t*0.18)*20;
  const sx = x + warp1x + warp2x, sy = y + warp1y + warp2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.85],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*110, 40+Math.cos(t*0.65+2)*60, 0.11, 1.8, 1.0],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.13, 2.1, 0.88],
    [200+Math.sin(t*0.25+6)*130, 220+Math.cos(t*0.45+3)*70, 0.055, 2.4, 1.12],
    [300+Math.cos(t*0.7+2)*90, 30+Math.sin(t*0.5+5)*80, 0.075, 1.6, 0.92]
  ];
  let aS=0, iS=0, cS=0, sS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const w1 = Math.sin(d*f - t*sp)*w;
    const w2 = Math.sin(d*f*0.618 + t*sp*0.7 + 0.5)*w*0.7;
    const w3 = Math.sin(d*f*1.618 - t*sp*0.4 + 1.2)*w*0.4;
    aS += w1 + w3*0.3;
    iS += w2 + w3*0.5;
    cS += Math.sin(d*f*0.5 - t*sp*1.2)*Math.cos(d*f*0.3 + t*sp*0.8)*w*0.6;
    sS += Math.sin(d*f*0.8 + t*sp*0.5 + Math.atan2(sy-sY,sx-sX)*2)*w*0.5;
  }
  aS/=10; iS/=10; cS/=10; sS/=10;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.06*Math.cos(t*0.1)+sy*0.05*Math.sin(t*0.15)+t*0.6)*0.3;
  const bg = bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5), sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.03-ang*5+t*0.8)*0.5;
  const spiral=(sp1+sp2)*0.4+sp3*0.2;
  const cell1=Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const cell2=Math.sin((sx*0.7+sy*0.7)*0.12+t*0.5)*Math.sin((sx*0.7-sy*0.7)*0.1-t*0.3);
  const cell=(cell1+cell2*0.5)*0.5;
  const cross=aS*iS*0.5 + cS*0.4 + sS*0.3;
  const diff = Math.tanh((aS - iS*0.7 + cross*0.3)*2.5);
  const react = Math.tanh((diff + bg*0.25 + spiral*0.3 + cell*0.2)*2.0);
  const pulse = 0.85+Math.sin(t*0.3)*0.15;
  const v = react*0.5+0.5;
  const vig = 1.0 - Math.sqrt(((x-240)/280)**2+((y-120)/160)**2)*0.15;
  const glow = Math.exp(-dist*0.005)*0.2*Math.sin(t*0.8)*0.5;
  const fv = Math.min(1, Math.max(0, v*pulse*vig + glow));
  const pal = [
    [5,12,55],[12,45,95],[18,90,120],[25,140,135],[60,175,145],
    [160,195,110],[220,190,70],[235,150,60],[225,100,70],[185,60,75],
    [120,30,65],[55,18,55],[20,10,45],[5,12,55]
  ];
  const idx=fv*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const edge=Math.abs(react)>0.65?1.12:1.0;
  const core=Math.abs(react)>0.85?1.06:1.0;
  const bright=edge*core;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*bright*pulse)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*bright*pulse)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*bright*pulse)|0
  ];
}
